import java.util.StringTokenizer;

public class bubblestrike {
    public static void main(String[] args) throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(f.readLine());
        int x = Integer.parseInt(st.nextToken());
        double prob = Double.parseDouble(st.nextToken());
        int pos = findPos(x, x, prob);
        System.out.println(pos);
    }

    public static int findPos(int x, int currentA, double prob) {
        if (currentA <= 0) {
            int pos = x; // placeholder; we need to return something, but recursion restructured
            // Actually we need to compute differently. Let's redefine to mimic loops.
            // Use iterative recursion: we'll use a different approach: call a helper that does the while loops
            return x;
        }
        // Simpler: just use recursion for the outer for loop and inner while as separate recursion? Too complex. Let's do a clean recursion: 
        // The following is a recursive version that mimics the loops:
        return recursiveHelper(x, x, x, prob);
    }

    // This recursive version is a direct translation of the loops
    private static int recursiveHelper(int x, int a, int pos, double prob) {
        if (a <= 0) {
            return pos;
        }
        // while loop inside
        int newPos = pos;
        while (newPos - a >= 0 && check(newPos - a, x - (newPos - a), prob)) {
            newPos -= a;
        }
        return recursiveHelper(x, a / 2, newPos, prob);
    }

    public static boolean check(int good, int bad, double proba) {
        double g = good;
        double b = bad;
        double ans = (0.25 * b * Math.max(0, b - 1.0) * g
                + (g * Math.max(0, g - 1) * Math.max(0, g - 2) / 6.0
                + b * 0.5 * g * Math.max(0, g - 1)))
                / ((g + b) * Math.max(0, g + b - 1) * Math.max(0, g + b - 2) / 6.0);
        return ans >= proba;
    }
}
